namespace BlazorApp.Models;

public class EquipmentItem
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

using BlazorApp.Models;

namespace BlazorApp.Services;

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate network/database latency
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new() { Id = 1, Name = "Forklift A",        Location = "Warehouse 1", LastInspected = new DateTime(2026, 6, 15) },
            new() { Id = 2, Name = "Conveyor Belt B",   Location = "Warehouse 2", LastInspected = new DateTime(2026, 5, 22) },
            new() { Id = 3, Name = "Drill Press C",     Location = "Shop Floor",  LastInspected = new DateTime(2026, 7, 1) },
            new() { Id = 4, Name = "Lathe D",           Location = "Shop Floor",  LastInspected = new DateTime(2026, 4, 10) },
            new() { Id = 5, Name = "Crane E",           Location = "Yard",        LastInspected = new DateTime(2026, 3, 30) },
            new() { Id = 6, Name = "Compressor F",      Location = "Utility Room",LastInspected = new DateTime(2026, 6, 28) },
            new() { Id = 7, Name = "Generator G",       Location = "Utility Room",LastInspected = new DateTime(2026, 2, 14) },
            new() { Id = 8, Name = "Pump H",            Location = "Warehouse 1", LastInspected = new DateTime(2026, 7, 5) },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@attribute [StreamRendering]
@using BlazorApp.Models
@using BlazorApp.Services
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? items;
    private PersistingComponentStateSubscription _subscription;

    protected override async Task OnInitializedAsync()
    {
        // Restore persisted state if available (interactive reconnect);
        // otherwise fetch from service (prerender/stream pass).
        _subscription = ApplicationState.RegisterOnPersisting(PersistData);

        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>("inventory", out var restored))
        {
            items = restored;
        }
        else
        {
            items = await EquipmentSvc.GetEquipmentAsync();
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson("inventory", items);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

